require_once __DIR__.'/includes/email.php';email_require('view');$id=(int)($_GET['id']??$_POST['id']??0);try{$message=email_message($id);}catch(Throwable){http_response_code(404);$pageTitle='ایمیل در دسترس نیست';require __DIR__.'/../views/partials/admin-header.php';echo '<section class="card"><h2>ایمیل در دسترس نیست</h2><p class="muted">این پیام وجود ندارد یا به حساب آن دسترسی ندارید.</p></section>';require __DIR__.'/../views/partials/admin-footer.php';exit;}EmailSyncService::markRead($id);$pageTitle=$message['subject']?:'بدون موضوع';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/email-message.php?id='.$id);}try{$action=(string)($_POST['action']??'');if(in_array($action,['note','assign','ticket','cartable'],true)&&!EmailHubModule::access($message,'reply'))throw new RuntimeException('email_internal_action_denied');if($action==='note'){Database::execute('UPDATE email_messages SET internal_note=?,updated_at=NOW() WHERE id=?',[trim((string)($_POST['internal_note']??'')),$id]);EmailHubModule::log((int)$message['account_id'],$id,'internal_note','یادداشت داخلی ایمیل بروزرسانی شد.');}elseif($action==='assign'){Database::execute('UPDATE email_messages SET assigned_user_id=?,assigned_group=?,status=IF(status IN ("new","read"),"pending_reply",status),updated_at=NOW() WHERE id=?',[(int)($_POST['assigned_user_id']??0)?:null,mb_substr(trim((string)($_POST['assigned_group']??'')),0,190)?:null,$id]);EmailHubModule::log((int)$message['account_id'],$id,'message_assigned','ایمیل ارجاع داده شد.');}elseif(in_array($action,['ticket','cartable'],true)){$integrationId=EmailSyncService::queueIntegration($id,$action,(int)Auth::user()['id']);EmailHubModule::log((int)$message['account_id'],$id,'integration_queued',$action==='ticket'?'درخواست تبدیل به تیکت ثبت شد.':'درخواست ارجاع به کارتابل ثبت شد.',null,['integration_id'=>$integrationId]);}elseif($action==='archive')EmailSyncService::moveMessage($id,'archive');elseif($action==='delete'){if(!EmailHubModule::access($message,'delete'))throw new RuntimeException('email_delete_denied');EmailSyncService::moveMessage($id,'trash');}else throw new InvalidArgumentException('عملیات معتبر نیست.');flash('عملیات ایمیل انجام شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){flash(email_safe_error($e),'danger');}redirect('/admin/email-message.php?id='.$id);}
