<div class="email-page-head"><div><h1><?=e($message['subject']?:'بدون موضوع')?></h1><p><?=e($message['account_title'].' · '.email_status_label($message['status']))?></p></div><div class="form-actions"><a class="btn" href="/admin/email-inbox.php?account_id=<?=$message['account_id']?>&message_id=<?=$id?>">بازگشت</a><a class="btn btn-primary" href="/admin/email-compose.php?type=reply&message_id=<?=$id?>">پاسخ</a></div></div>
<div class="email-message-layout"><main><section class="card email-message-card"><header><div><strong><?=e($message['from_name']?:$message['from_email'])?></strong><span dir="ltr"><?=e($message['from_email'])?></span></div><time><?=e($message['date_received']?format_jalali_datetime($message['date_received']):'—')?></time></header><details class="email-header-details"><summary>نمایش گیرندگان و Header خلاصه</summary><dl><div><dt>به</dt><dd><?=e(email_addresses_text($message['to_json']))?></dd></div><div><dt>رونوشت</dt><dd><?=e(email_addresses_text($message['cc_json'])?:'—')?></dd></div><div><dt>Message-ID</dt><dd dir="ltr"><?=e($message['message_id']?:'—')?></dd></div></dl></details><div class="email-preview-actions"><a class="btn btn-small" href="/admin/email-compose.php?type=reply&message_id=<?=$id?>">پاسخ</a><a class="btn btn-small" href="/admin/email-compose.php?type=reply_all&message_id=<?=$id?>">پاسخ به همه</a><a class="btn btn-small" href="/admin/email-compose.php?type=forward&message_id=<?=$id?>">فوروارد</a><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="link-btn" name="action" value="archive">آرشیو</button></form><?php if(EmailHubModule::access($message,'delete')):?><form method="post" onsubmit="return confirm('ایمیل به حذف‌شده‌ها منتقل شود؟')"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="link-btn danger" name="action" value="delete">حذف نرم</button></form><?php endif?></div><?php if($message['body_html']):?><iframe class="email-body-frame full" sandbox srcdoc="<?=e('<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data: cid:; style-src \'unsafe-inline\'"><div dir="auto">'.$message['body_html'].'</div>')?>"></iframe><?php else:?><div class="email-text-body"><?=nl2br(e($message['body_text']))?></div><?php endif?><?php if($attachments):?><section><h3>پیوست‌ها</h3><ul class="email-attachments"><?php foreach($attachments as $a):?><li><a class="btn btn-small" href="/admin/email-attachment.php?id=<?=$a['id']?>">دانلود <?=e($a['file_name'])?></a><small><?=e(number_format($a['file_size']/1024,0))?> کیلوبایت</small></li><?php endforeach?></ul></section><?php endif?></section></main><aside class="email-message-sidebar"><section class="card"><h2>ارجاع داخلی</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="assign"><label class="form-field"><span>ارجاع به کاربر</span><select name="assigned_user_id"><option value="">بدون ارجاع</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=(int)$message['assigned_user_id']===(int)$u['id']?'selected':''?>><?=e($u['name'].' — '.$u['department'])?></option><?php endforeach?></select></label><label class="form-field"><span>گروه داخلی</span><input name="assigned_group" value="<?=e($message['assigned_group']??'')?>"></label><button class="btn btn-primary">ارجاع</button></form></section><section class="card"><h2>یادداشت داخلی</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="note"><textarea name="internal_note" rows="5" placeholder="این یادداشت برای گیرنده ایمیل ارسال نمی‌شود."><?=e($message['internal_note']??'')?></textarea><button class="btn">ذخیره یادداشت</button></form></section><section class="card"><h2>تیکت و کارتابل</h2><div class="email-integration-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-primary" name="action" value="ticket">تبدیل به تیکت</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn" name="action" value="cartable">ارسال به کارتابل</button></form></div><?php foreach($integrations as $integration):?><small><?=e(($integration['integration_type']==='ticket'?'تیکت':'کارتابل').' — '.(['pending'=>'در انتظار اتصال','completed'=>'انجام‌شده','failed'=>'ناموفق'][$integration['status']]??''))?></small><?php endforeach?></section></aside></div><?php require __DIR__.'/../views/partials/admin-footer.php';?>
